<script setup lang="ts">
import { onMounted, ref } from 'vue'
import Projects from './components/Projects.vue'
import Jobs from './components/Jobs.vue'
import Knowledge from './components/Knowledge.vue'
import WikiSources from './components/WikiSources.vue'
import Settings from './components/Settings.vue'
import { token, api, action, failure, notice, type Workspace } from './api'
import './style.css'
const navigation=[{id:'projects',label:'项目'},{id:'jobs',label:'后台任务'},{id:'document',label:'知识库'},{id:'wiki',label:'Wiki'},{id:'wiki-sources',label:'Wiki 目录'},{id:'memory',label:'长期记忆'},{id:'models',label:'模型设置'},{id:'credentials',label:'MCP 接入'}] as const
const section=ref<string>('projects'),workspaces=ref<Workspace[]>([]),selected=ref(''),authenticated=ref(false),status=ref<any>(null),pending=ref(''),busy=ref(false)
async function refresh(){const collected:Workspace[]=[];let cursor='';do{const value=await api('/workspaces?limit=100'+(cursor?'&after='+cursor:''));collected.push(...value.items);cursor=value.next_cursor||''}while(cursor);workspaces.value=collected;if(!workspaces.value.find(w=>w.workspace_id===selected.value))selected.value=workspaces.value[0]?.workspace_id||''}
async function navigate(id:string){section.value=id;if(id==='projects')await action(refresh,'项目状态已更新')}
async function login(){busy.value=true;token.value=pending.value;await action(async()=>{await refresh();authenticated.value=true;pending.value=''},'已连接管理服务');if(!authenticated.value)token.value='';busy.value=false}
function logout(){token.value='';pending.value='';authenticated.value=false;workspaces.value=[];notice.value='';failure.value=''}
onMounted(async()=>{try{status.value=await(await fetch('/api/v1/service/status')).json();if(status.value.auth_mode==='local'){await refresh();authenticated.value=true}}catch{failure.value='服务连接失败，请检查服务状态'}})
</script>
<template><div class="shell"><aside><div class="brand"><span class="logo">M</span>Memory Center</div><nav><button v-for="item in navigation" :key="item.id" :class="{current:section===item.id}" @click="navigate(item.id)" :disabled="!authenticated"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="5" width="16" height="14" rx="2"/><path d="M8 10h8M8 14h5"/></svg>{{item.label}}</button></nav><div class="sidebar-bottom"><span :class="['state',status?.ready?'active':'paused']">{{status?.ready?'服务就绪':'连接中'}}</span><small>{{status?.version}}</small><button v-if="authenticated&&status?.auth_mode!=='local'" @click="logout">退出管理</button></div></aside><main><template v-if="!authenticated"><div class="page-title"><div><h1>连接管理服务</h1><p>输入本机服务的管理员令牌，管理项目与知识空间。</p></div></div><form class="form-panel login" @submit.prevent="login"><label>管理员令牌<input type="password" v-model="pending" autocomplete="off" required aria-label="管理员令牌"></label><p class="muted">令牌位于服务数据目录的 admin-token 文件。仅保存在当前页面内存中，刷新后需重新输入。</p><button class="primary" :disabled="busy">{{busy?'正在连接…':'连接'}}</button></form></template><template v-else><div class="workspace-bar"><label>当前项目<select v-model="selected"><option v-for="workspace in workspaces" :key="workspace.workspace_id" :value="workspace.workspace_id">{{workspace.name}}{{workspace.status==='paused'?'（已暂停）':''}}</option><option v-if="!workspaces.length" value="">尚无项目</option></select></label><span>MCP <code>/mcp</code></span></div><Projects v-if="section==='projects'" :workspaces="workspaces" :selected="selected" @select="selected=$event" @refresh="action(refresh,'项目已更新')"/><Jobs v-else-if="section==='jobs'"/><WikiSources v-else-if="section==='wiki-sources'" :workspaces="workspaces"/><Knowledge v-else-if="section==='document'||section==='wiki'||section==='memory'" :workspace="selected" :kind="section as 'document'|'wiki'|'memory'"/><Settings v-else-if="section==='models'||section==='credentials'" :key="section" :section="section as 'models'|'credentials'" :workspaces="workspaces" :local="status?.auth_mode==='local'"/></template><div v-if="failure||notice" role="status" :class="['message',failure?'error':'success']">{{failure||notice}}<button @click="failure='';notice=''" aria-label="关闭消息">关闭</button></div></main></div></template>
